add('03_001','刀刃竖向局部在右前，弯曲袍袖横占下部；只有刀的局部运动轨迹。',['袍袖','刀刃'],['刀刃产生竖向掠动'],['刃面与袖面分层'],'灰白留白',[ ],'Action，竖向掠动在镜内完成局部短行程；03_002高举柄的手提示向上收刀，不补攻击。',['刀刃在袖侧',[ '沿竖向提起一段'],'为抬高握持做局部接续','刃下端继续向上离开袖侧'],'与02_003竖刃直接接续；只上提局部行程，未描写衣袖伤口或刺入。',2,['100mm平视刀与袍袖特写，袍袖横占下部，银灰刀面在右前竖起；固定机位，刀的运动区留在右侧。','银灰刀刃沿袖侧迅速向上掠起，下端一闪越过黑色袖面，细小亮点在行程下方短短散开。袖面弧线保持平稳，刀继续升出上缘。','背景仅在上缘留有深灰蓝低亮水面，空间远退，近层关系清晰。','无台词。','刃面冷白反光形成窄亮带，深灰袍袖上缘保留柔光，下部阴影厚实。','一声短促刀刃破风，衣料轻擦声随后收住。'],flags=[])
add('03_002','春子朝右侧脸近景，握刀手在左前，黑刀斜过肩前。',['春子','握刀手','刀'],['抓紧刀柄'],['侧脸朝右','内眉高外眉低'],'渐变灰底',[['还没明白自己的处境吗?','春子','まだ自分の立場が分かってないの？'],['在我倒数完之前说出来.','春子','数え終わるまでに話して。']],'Mixed，接上抬高刀柄，握紧后以前倾盘问；侧脸为中段锚点。',['手已抬到头旁',['收紧握柄','头向前微倾并说出期限'],'握持任务与逼问相互加压','头稍抬起，仍向右凝视'],'两轮短句同侧脸，握紧由源动作兑现；没有提前倒数或添加劈砍。',8,['70mm平视春子侧脸近景，脸朝右，握刀手在左前大近层，黑色刀背斜越肩前；固定机位，侧脸与握持同框。','春子的手指向掌心收紧，柄缠布被压实。她顺着画面右侧向前压近，眼睛沿右下方审视，眉头高挑、眉尾低压；说到期限时下颌略抬，嘴唇清楚合上，握柄的力道持续。','远层水面深灰蓝，暗色群像化为低对比轮廓，留白区域保持冷静纵深。','春子说：“まだ自分の立場が分かってないの？数え終わるまでに話して。”（低女声，前句逼问，停半拍后明确期限，重音坚定，语速自然。）','冷白柔光贴亮侧脸、耳廓与指背，棕发内层、衣领和刀背保持深暗。','柄缠布轻微受压摩擦，低柔水声不断，尾段呼吸变短。'])
add('03_003','兜帽侧部填满画面，黑面向右，右缘短刺状流线及白弧线。',['兜帽','黑色局部流线'],['帽缘附近局部纹理振动'],['帽内黑面朝右'],'主体完全遮挡',[ ],'State，帽缘已有流动短收放，无帽下身体变化。',['帽侧黑面稳定',['毛边细线短短起伏'],'回应沉默，保留对峙的窄隙','细线仍在帽缘'],'物件停留两秒用于无回应，不添加摇头或脱帽。',2,['100mm平视帽侧极近景，灰黑兜帽从左上覆盖中央，内侧黑面朝右，右缘窄带容纳细流线；固定机位。','帽缘的黑色细线短短伸长，随即收向边缘；几条冷白弧线沿外侧滑过，帽的曲面始终稳定，余下细线继续微弱起伏。','独立背景完全被主体遮住。','无台词。','兜帽曲面由暗灰向黑渐深，冷白细亮纹勾出右缘，黑面保留细微层次。','细弱气流擦过，低柔水声在远处持续。'],flags=[],bgmode='occluded')
